<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import api from '@/api/client'
const router=useRouter(), form=reactive({customer_name:'',phone:'',email:'',plate_number:'',vehicle_type:'motor',brand:'',model:'',service_id:'',complaint:'',booking_date:'',slot_time:''}), services=ref([]), slots=ref([]), error=ref(''), busy=ref(false), code=ref('')
const tomorrow=()=>{const d=new Date();d.setDate(d.getDate()+1);return d.toISOString().slice(0,10)}
form.booking_date=tomorrow()
const loadSlots=async()=>{if(!form.booking_date)return;try{slots.value=(await api.get('/public/booking-slots',{params:{date:form.booking_date}})).data.data;error.value=''}catch(e){slots.value=[];error.value=e.response?.data?.message||'Tanggal tidak dapat dipakai.'}}
watch(()=>form.booking_date,loadSlots); onMounted(async()=>{services.value=(await api.get('/public/services')).data.data;loadSlots()})
async function submit(){busy.value=true;error.value='';try{code.value=(await api.post('/public/bookings',form)).data.data.booking_code}catch(e){error.value=e.response?.data?.message||'Booking gagal.';loadSlots()}finally{busy.value=false}}
const selected=computed(()=>slots.value.find(s=>s.time===form.slot_time))
</script>
<template><section><h1>Booking servis</h1><p v-if="code" class="service-success">Booking berhasil. Kode: <RouterLink :to="`/booking/${code}`">{{code}}</RouterLink></p><form v-else @submit.prevent="submit" class="grid gap-4 md:grid-cols-2 lg:grid-cols-4"><div class="min-w-0 md:col-span-1"><label class="mb-1 block font-semibold text-ink">Tanggal<input v-model="form.booking_date" type="date" class="service-input" required></label><div class="flex flex-wrap gap-2"><button v-for="slot in slots" :key="slot.time" type="button" class="btn" :class="form.slot_time===slot.time?'btn-primary':'btn-outline-primary'" :disabled="!slot.available" @click="form.slot_time=slot.time">{{slot.time}} ({{slot.remaining}})</button></div></div><div class="min-w-0 md:col-span-1"><label class="mb-1 block font-semibold text-ink">Nama<input v-model="form.customer_name" class="service-input" required></label><label class="mb-1 block font-semibold text-ink">Telepon<input v-model="form.phone" class="service-input" required></label><label class="mb-1 block font-semibold text-ink">Email<input v-model="form.email" type="email" class="service-input"></label><label class="mb-1 block font-semibold text-ink">Plat<input v-model="form.plate_number" class="service-input" required></label><div class="row"><label class="col mb-1 block font-semibold text-ink">Jenis<select v-model="form.vehicle_type" class="service-input"><option value="motor">Motor</option><option value="mobil">Mobil</option></select></label><label class="col mb-1 block font-semibold text-ink">Merek<input v-model="form.brand" class="service-input" required></label><label class="col mb-1 block font-semibold text-ink">Model<input v-model="form.model" class="service-input" required></label></div><label class="mb-1 block font-semibold text-ink">Jasa<select v-model="form.service_id" class="service-input"><option value="">Pilih jasa</option><option v-for="s in services" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label class="mb-1 block font-semibold text-ink">Keluhan<textarea v-model="form.complaint" class="service-input"></textarea></label><p v-if="error" class="text-red-800">{{error}}</p><button class="service-primary" :disabled="busy||!selected">{{busy?'Mengirim…':'Buat booking'}}</button></div></form></section></template>
